function pb.evidence(Vo,Wo,Xo)
local Yo=type(Xo.nums)==cHe[2220]and Xo.nums or{}
local Zo=Vo.firstPlaced[Wo]
if not Zo then
return{why=cHe[2626]}
end
local _o={}
for ap,bp in ipairs(Xo.buffs or{})do
_o[bp]=true
end
local function cp(dp)
if#dp==0 then
return nil
end
table.sort(dp)
return dp[math.ceil(#dp/2)]
end
if Xo.family==cHe[2414]then
if(Vo.sales or 0)==0 then
return{why=cHe[2627]}
end
local ep,fp
for ip in pairs(Vo.own)do
local jp,kp,lp,mp,np=0,0,0,0,0
for op,pp in pairs(Vo.copies)do
local qp=pp.buff[ip]or 0
if(pp.sold or 0)>0 then
if pp.id~=Wo then
mp=mp+1
end
if qp>0 then
if pp.id==Wo then
jp=jp+1
else
lp=lp+1
end
np=math.max(np,qp)
end
elseif qp>0 then
kp=kp+1
end
end
if jp>0 and kp==0 and(not fp or jp>fp)then
ep,fp={name=ip,other=lp,otherAfter=mp,top=np},jp
end
end
if not ep then
return{why=cHe[2628]}
end
local rp=(ep.other>0 and cHe[1150])or(ep.otherAfter>0 and cHe[2629])or cHe[2630]
return{seen=true,buff=ep.name,who=rp,nums={stacks=(Vo.sales>1 and ep.top>1)or nil,sales=Vo.sales},why=string.format(cHe[2631],fp,ep.name,rp==cHe[2629]and cHe[2632]or cHe[1139])}
end
local vp=Xo.trigger and tostring(Xo.trigger):find(cHe[2633],1,true)~=nil
local wp=0
for yp,zp in ipairs(Vo.casts)do
if zp.id==Wo then
wp=wp+1
end
end
if vp and wp==0 and(Xo.family==cHe[2415]or Xo.family==cHe[2412])then
return{why=cHe[2634]}
end
if Xo.family==cHe[2415]then
local Ap,Bp,Cp
for Dp,Ep in pairs(Vo.own)do
if Ep.first>=Zo-1 and(_o[Dp]or Ep.first<=Zo+5 or vp)and(not vp or pb.nearCast(Vo,Wo,Ep.starts)>0)then
local Fp=0
for Gp,Hp in pairs(Ep.by)do
if Gp~=Wo then
Fp=Fp+Hp
end
end
if Fp>0 and(not Ap or(_o[Dp]and not Cp)or((_o[Dp]or false)==(Cp or false)and Fp>Bp))then
Ap,Bp,Cp=Dp,Fp,_o[Dp]
end
end
end
if not Ap then
return{why=cHe[2635]}
end
return{seen=true,buff=Ap,why=string.format(cHe[2636],Ap)}
end
if Xo.family==cHe[2412]then
local Ip,Jp
for Kp,Lp in pairs(Vo.foeBuffs)do
if Lp.first>=Zo-1 and Lp.near>0 and(_o[Kp]or Lp.near>=0.5*Lp.n)and(not vp or pb.nearCast(Vo,Wo,Lp.onsets)>0)then
local Mp=Lp.near+(_o[Kp]and 1e6 or 0)+(vp and pb.nearCast(Vo,Wo,Lp.onsets)*1000 or 0)
if not Jp or Mp>Jp then
Ip,Jp=Kp,Mp
end
end
end
if not Ip then
return{why=cHe[2637]}
end
local Np=Vo.foeBuffs[Ip]
local Op={}
if#Np.durs>=3 then
Op.secsSeen=math.floor(cp(Np.durs)*10+0.5)/10
elseif Np.foes>=5 then
Op.keepSeen=true
end
if Np.spN>=5 then
local Pp=Np.sp/Np.spN
if Pp<0.97 then
Op.slowSeen=math.floor((1-Pp)*100+0.5)/100
end
end
if Yo.chance and(Vo.nearN or 0)>0 then
Op.chanceSeen=math.floor(math.min(1,Np.foes/Vo.nearN)*100+0.5)/100
end
Op.bossToo=Np.boss>0 or nil
return{seen=true,buff=Ip,nums=Op,why=string.format(cHe[2638],Np.foes,Ip)}
end
if Xo.family==cHe[2469]then
local Qp=(tonumber(Yo.below)or 0.25)+0.02
local Rp,Sp=0,0
for Tp,Vp in ipairs(Vo.deaths)do
if not Vp.boss then
Sp=Sp+1
if Vp.frac>0.04 and Vp.frac<=Qp then
Rp=Rp+1
end
end
end
if Sp<10 then
return{why=cHe[2639]}
end
local Wp=Rp/Sp
if Wp<0.3 then
return{why=string.format(cHe[2640],math.floor(Wp*100))}
end
return{seen=true,nums={shareSeen=math.floor(Wp*100+0.5)/100},why=string.format(cHe[2641],Rp,Sp,math.floor(Qp*100))}
end
if Xo.family==cHe[2318]then
local Xp={}
for Yp,Zp in ipairs(Vo.summons)do
if Zp.owner==Wo then
table.insert(Xp,Zp)
end
end
if#Xp<2 then
return{why=cHe[2642]}
end
table.sort(Xp,function(_p,aq)
return _p.born<aq.born
end)
local bq,cq,dq={},{},{}
for eq=2,#Xp do
local fq=(Xp[eq].tk or 0)-(Xp[eq-1].tk or 0)
if fq>0 then
table.insert(bq,fq)
end
end
for gq,hq in ipairs(Xp)do
if hq.died then
table.insert(cq,hq.died-hq.born)
end
table.insert(dq,{hq.born,1})
table.insert(dq,{hq.died or hq.last or hq.born,-1})
end
table.sort(dq,function(iq,jq)
return iq[1]<jq[1]
end)
local kq,lq=0,0
for mq,nq in ipairs(dq)do
kq=kq+nq[2]
lq=math.max(lq,kq)
end
local oq=cp(cq)
return{seen=true,nums={everySeen=cp(bq),lifeSeen=oq and math.floor(oq+0.5)or nil,capSeen=lq,made= #Xp},why=string.format(cHe[2643],#Xp)}
end
if Xo.family==cHe[2416]then
local pq,qq
for rq,sq in pairs(Vo.own)do
if(sq.by[Wo]or 0)>0 and sq.first>=Zo-1 and(not pq or(_o[rq]and not _o[pq]))then
pq,qq=rq,sq
end
end
local tq
for uq,vq in ipairs(Vo.transforms)do
if vq.from==Wo then
tq=vq.to
end
end
if not pq then
local wq,xq,yq
for zq,Aq in pairs(Vo.copies)do
if Aq.id==Wo or(tq and Aq.id==tq)then
for Bq,Cq in pairs(Aq.stat or{})do
if Cq.hi>Cq.lo and(not wq or(Cq.hi-Cq.lo)>(yq-xq))then
wq,xq,yq=Bq,Cq.lo,Cq.hi
end
end
end
end
if not wq then
return{why=cHe[2644]}
end
return{seen=true,nums={stat=wq,loSeen=xq,hiSeen=yq,transformTo=tq},why=string.format(cHe[2645],wq,tostring(xq),tostring(yq))}
end
