rs.typed[ss]=math.max(rs.typed[ss]or 0,(tonumber(ts)or 0)*qs)
end
local us=tonumber(js.dmgMax)or tonumber(js.dmg)
if us then
rs.dmg=math.max(rs.dmg or 0,us*qs)
end
if js.crit then
rs.crit=math.max(rs.crit or 0,(tonumber(js.crit)or 0)*qs)
end
Wr.aura,Xr=rs,true
elseif hs.family==cHe[2412]then
local vs=pb.KW[tostring(hs.keyword or cHe[1139])]
