if vs and vs.kind==cHe[2402]and not(type(js.shred)==cHe[2220])then
local As=tonumber(js.amp)
local Bs=Sr and((type(Sr.ampTypes)==cHe[2220]and Sr.ampTypes[vs.dtype])or(tonumber(Sr.amp)or 0)>0)
if As and As>0 and not Bs then
Wr.fx,Xr=(Wr.fx or 0)+As*V.TYPED_AMP_SHARE*zs*Zr,true
end
elseif vs and(vs.kind==cHe[2349]or vs.kind==cHe[2410])then
if not(Sr and((tonumber(Sr.stun)or 0)>0 or(tonumber(Sr.slowTime)or 0)>0))then
Wr.stun=(vs.kind==cHe[2410]and 0.5 or 1)*xs
if js.slow then
Wr.slowP,Wr.slowT=tonumber(js.slow),xs
end
Xr=true
end
elseif vs and vs.kind==cHe[2351]then
if not(Sr and(tonumber(Sr.slowTime)or 0)>0)then
Wr.slowP,Wr.slowT,Xr=tonumber(js.slow)or tonumber(js.slowSeen)or 0.3,xs,true
end
elseif vs and vs.kind==cHe[2409]then
local Cs=tonumber(js.dot)or 0
if Cs>0 and(tonumber(Sr and Sr.dot)or 0)<Cs*0.5 then
local Ds=math.min(1.5,Cs)*ws
Wr.dot,Xr=(Wr.dot or 0)+Ds,true
