end
end
if type(js.ampFrom)==cHe[2220]and tostring(js.ampFrom.kind)==cHe[2062]and(tonumber(js.ampFrom.amp)or 0)>0 then
local Es=(type(js.secsBy)==cHe[2220]and#js.secsBy>0)and js.secsBy or{tonumber(js.secsSeen)or tonumber(js.secs)or 5}
