function mb.weatherStrength(pE)
local qE=mb.fx(pE)
local rE=qE.dmg/qE.cd/qE.hp/qE.speed*(1+(qE.range-1)/2)
for sE,tE in pairs(qE.kinds)do
rE=rE*(1+bb.rogueShare(sE)*tE)
end
if qE.ice>0 then
local uE=bb.rogueShare(cHe[2365])
rE=rE*(uE+(1-uE)/(1-qE.ice+qE.ice/gb.modFactor(cHe[2772])))
end
if qE.fly>0 then
rE=rE*(1-qE.fly*0.5)
end
if qE.noCC then
rE=rE*0.95
end
if qE.shroud then
rE=rE*0.9
end
if qE.zap then
rE=rE*0.85
end
return rE/mb.weatherK(pE)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(vE)
local wE=vE and type(P.hunt)==cHe[2220]and type(P.hunt.wk)==cHe[2220]and P.hunt.wk[tostring(vE)]or nil
return type(wE)==cHe[2220]and tonumber(wE.k)or 1
end
function mb.weatherLearn()
if bb.withOthers or#game:GetService(cHe[1118]):GetPlayers()>1 then
return
end
local xE=bb.huntWeather or mb.weatherNow()
local yE,zE=bb.pred,bb.calRun
if not xE or type(yE)~=cHe[2220]or type(zE)~=cHe[2220]then
return
end
local function AE(BE,CE)
return type(BE)==cHe[2220]and tonumber(BE[CE]or BE[tostring(CE)])or nil
end
local DE={}
for EE=2,bb.wave()do
local FE,GE=AE(zE.alive,EE),AE(yE.aliveAt,EE)
if FE and GE and FE>0 and GE>0 then
table.insert(DE,FE/GE)
end
end
if#DE<3 then
return
end
table.sort(DE)
local HE=DE[math.ceil(#DE/2)]
P.hunt.wk=type(P.hunt.wk)==cHe[2220]and P.hunt.wk or{}
local IE=P.hunt.wk[tostring(xE)]
local JE=math.min(mb.WEATHER_K_RUNS-1,type(IE)==cHe[2220]and tonumber(IE.n)or 0)
local KE=mb.weatherK(xE)
local LE=math.max(1,JE)
local ME=math.exp((LE*math.log(KE)+math.log(KE*HE))/(LE+1))
ME=U.clamp(ME,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(xE),old=IE}
P.hunt.wk[tostring(xE)]={k=ME,n=(type(IE)==cHe[2220]and tonumber(IE.n)or 0)+1,at=os.time()}
F.log(1,cHe[2773],string.format(cHe[2774],tostring(xE),HE,tostring(xE),ME,KE,P.hunt.wk[tostring(xE)].n))
end
function mb.cardGems(NE,OE)
