local QE=mb.pearlsFrom(OE+1,50)
for RE,SE in pairs(type(NE.effects)==cHe[2220]and NE.effects or{})do
if type(SE)==cHe[2220]then
local TE=tonumber(SE.amount)or 0
if SE.type==cHe[2775]then
PE=PE+math.abs(TE)*QE*O.pearlValue
elseif SE.type==cHe[2776]then
local UE,VE=pcall(W.rewardValue,SE.reward)
if UE then
PE=PE+(tonumber(VE)or 0)
end
elseif SE.type==cHe[2777]then
PE=PE+TE*mb.STARFALL_GEMS
elseif SE.type==cHe[2778]then
PE=PE+TE*100
