local XE=mb.board()
if WE and XE and NE.weather~=cHe[2720]and not XE.weathers[NE.weather]then
PE=PE+(1000+5000*O.pearlValue+50*W.remnantGems(cHe[2718]))/mb.WEATHERS
end
end
return PE
end
