mb.BONUS_BAR,mb.BONUS_SWAPS=1.3,4
function mb.bonusTeam(tF,uF,vF)
if type(tF)~=cHe[2220]or type(uF)~=cHe[2220]or#uF==0 then
return nil
end
local wF,xF=U.now(),N.session()
vF=tonumber(vF)or 12
