local function BF(CF,DF)
local EF,FF=gb.teamFrom(CF,tF.map),0
for GF,HF in ipairs({1,0.92,1.08})do
if gb.run(tF,EF,{hpMul=DF*HF}).won then
FF=FF+1
end
task.wait()
if FF>=2 then
return true
end
if GF==2 and FF==0 then
return false
end
end
return false
end
local IF=(BF(uF,mb.BONUS_BAR)and mb.BONUS_BAR)or(BF(uF,1)and 1)or nil
if not IF then
return nil
end
local JF=gb.grownKinds()>=gb.GROWN_MIN
local KF={}
for LF,MF in pairs(xF.profile_data.collection.owned_units)do
local NF=xF.collection:get_unit_by_uuid(MF.uuid)or MF
local OF=(mb.unitDrop(NF,AF))
if OF>0 and N.Units[NF.unit_id]and V.rows(NF.unit_id)and not V.hidden(NF.unit_id)then
local PF,QF=pcall(N.USC.calculate_level,NF.unit_id,tonumber(NF.xp)or 0)
if V.isFarm(NF.unit_id)or not JF or(PF and(tonumber(QF)or 0)>=gb.GROWN_LEVEL)then
local RF,SF=pcall(V.score,NF,tF.mod)
SF=(RF and tonumber(SF)or 0)*V.eventMul(NF,tF.ld)
if not KF[NF.unit_id]or SF>KF[NF.unit_id].sc then
KF[NF.unit_id]={u=NF,d=OF,sc=SF}
end
end
end
end
local TF={}
for UF,VF in pairs(KF)do
table.insert(TF,VF)
end
table.sort(TF,function(WF,XF)
if WF.d~=XF.d then
return WF.d>XF.d
end
return WF.sc>XF.sc
end)
if#TF==0 then
return nil
end
local YF,ZF=table.clone(uF),{}
local _F=mb.teamDrop(YF,AF)
local aG=gb.realShares(tF.key,5)
local function bG(cG)
local dG,eG={},0
pcall(gb.run,tF,gb.teamFrom(cG,tF.map),{hpMul=1,dealt=dG})
task.wait()
for fG,gG in pairs(dG)do
eG=eG+(tonumber(gG)or 0)
end
local hG={}
for iG,jG in ipairs(cG)do
hG[jG.unit_id]=tonumber(aG[jG.unit_id])or(((tonumber(dG[V.name(jG.unit_id)])or 0)+(tonumber(dG[cHe[2799]..tostring(jG.unit_id)])or 0))/math.max(1,eG))
end
return hG
end
local kG=bG(YF)
for lG=1,mb.BONUS_SWAPS do
if mb.teamDrop(YF,AF)>=1 or U.now()-wF>vF then
break
end
local mG=false
for nG,oG in ipairs(TF)do
if U.now()-wF>vF then
break
end
local pG=false
for qG,rG in ipairs(YF)do
if rG.uuid==oG.u.uuid or V.sameGroup(rG.unit_id,oG.u.unit_id)then
pG=true
break
end
end
if not pG then
local sG={}
for tG,uG in ipairs(YF)do
if(mb.unitDrop(uG,AF))<oG.d then
table.insert(sG,{i=tG,sc=(tonumber(kG[uG.unit_id])or 0)+((V.isFarm(uG.unit_id)or V.allyBuff(uG.unit_id))and 1e300 or 0)})
end
end
table.sort(sG,function(vG,wG)
return vG.sc<wG.sc
end)
for xG=1,math.min(2,#sG)do
local yG=table.clone(YF)
local zG=yG[sG[xG].i]
yG[sG[xG].i]=oG.u
if mb.teamDrop(yG,AF)>mb.teamDrop(YF,AF)+1e-6 and BF(yG,IF)then
table.insert(ZF,string.format(cHe[2800],V.name(oG.u.unit_id),V.name(zG.unit_id)))
YF,mG=yG,true
kG=bG(YF)
break
end
end
end
if mG then
break
end
end
if not mG then
break
end
end
if#ZF==0 then
return nil
end
return YF,string.format(cHe[2801],table.concat(ZF,cHe[2344]),math.floor(mb.teamDrop(YF,AF)*100+0.5),math.floor(_F*100+0.5),IF)
end
