function mb.skinTick()
if not(O.skinSmart or O.starOpen)or not(P.live.event and mb.is(P.live.event.level))then
return
end
if(F.req.back.skins or 0)>U.now()then
return
end
local WH=N.session()
local function XH(YH,ZH,_H)
local aI=F.gameSaid(ZH)
ab.pickNote.skins=string.format(cHe[2826],YH,tostring(aI or _H or cHe[2767]))
F.log(1,cHe[2737],ab.pickNote.skins)
F.backoff(cHe[2827],1800)
end
local bI=mb.skinPlan()
if O.skinSmart then
local cI=bI.wear[1]
if cI and(F.req.back.skinWear or 0)<=U.now()then
local dI=kb.slotOf(cI.unit)
if dI then
P.str.reequip={uuid=cI.unit,slot=dI}
F.saveNow()
F.request(cHe[2828],cHe[2829],cI.unit)
local eI=U.now()
while U.now()-eI<4 and kb.slotOf(cI.unit)do
task.wait(0.25)
end
end
local fI=U.now()
local gI,hI=F.request(cHe[2830],cHe[2760],cI.uuid,{unit_uuid=cI.unit})
local function iI()
local jI=WH.collection:get_unit_by_uuid(cI.unit)
return jI and jI.skin~=nil
end
while U.now()-fI<5 and not iI()do
task.wait(0.25)
end
if dI then
kb.reequip()
end
if iI()then
F.log(1,cHe[2737],string.format(cHe[2831],cI.name,cI.unitName))
ab.pickNote.skins=nil
bI=mb.skinPlan()
else
local kI=F.gameSaid(fI)
ab.pickNote.skins=string.format(cHe[2832],cI.name,tostring(kI or hI or cHe[2767]))
F.log(1,cHe[2737],ab.pickNote.skins)
F.backoff(cHe[2830],1800)
end
end
if#bI.sell>0 then
local lI,mI={},0
for nI=1,math.min(50,#bI.sell)do
table.insert(lI,bI.sell[nI].uuid)
mI=mI+bI.sell[nI].pearls
end
local oI=tonumber(N.cur(cHe[2797]))or 0
local pI=U.now()
local qI,rI=F.request(cHe[2833],cHe[2765],lI)
while U.now()-pI<5 and(tonumber(N.cur(cHe[2797]))or 0)<=oI do
task.wait(0.25)
end
local sI=(tonumber(N.cur(cHe[2797]))or 0)-oI
if sI<=0 then
return XH(cHe[2834],pI,rI)
end
cb.add(string.format(cHe[2835],#lI),#lI,cHe[2827],string.format(cHe[2836],U.fmt(sI)))
ab.pickNote.skins=nil
