if not hR or(iR and not dR.won)or(hR and not iR and dR.won)then
local jR,kR=pcall(gb.styleP,dR)
eR,fR=(jR and tonumber(kR))or tonumber(dR.p),W.IC.SIM_W
end
end
return(cR*2+eR*fR)/(bR+2+fR)
