local Wab=type(Uab)==cHe[2220]and tonumber(Uab.price)or nil
if Vab and Wab and Wab<=Qab then
local Xab=Mab[Uab.item_id]or 0
if Nab<Pab or Xab==0 then
if not Rab or Xab<Rab.have or(Xab==Rab.have and Vab<Rab.pr)then
Rab={index=Sab,item_id=Uab.item_id,price=Wab,have=Xab,pr=Vab}
