function ab.defEquipPlan(Yab,Zab)
local _ab,abb,bbb=0,{},{}
for cbb,dbb in ipairs(Yab)do
if dbb.equipped then
_ab=_ab+1
abb[dbb.item_id]=true
elseif ab.DEF_WANT[dbb.item_id]and(dbb.d==nil or dbb.d>0)then
table.insert(bbb,dbb)
end
end
local ebb={}
while _ab+ #ebb<Zab and#bbb>0 do
table.sort(bbb,function(fbb,gbb)
local hbb,ibb=abb[fbb.item_id]and 1 or 0,abb[gbb.item_id]and 1 or 0
if hbb~=ibb then
return hbb<ibb
end
if ab.DEF_WANT[fbb.item_id]~=ab.DEF_WANT[gbb.item_id]then
return ab.DEF_WANT[fbb.item_id]<ab.DEF_WANT[gbb.item_id]
end
return fbb.g>gbb.g
end)
local jbb=table.remove(bbb,1)
abb[jbb.item_id]=true
table.insert(ebb,jbb)
end
return ebb
end
