function kb.gainXp(Ydb,Zdb)
local _db,aeb=tonumber(Ydb.xp)or 0,kb.xpFor(Ydb.unit_id,kb.cap(Ydb))
local beb=math.max(0,aeb-_db)
if beb<=0 or(Zdb or 0)<=0 then
return 0,0
end
local ceb=math.min(Zdb,beb)
local deb=kb.base(Ydb)
if deb<=0 then
return 0,ceb
end
return kb.share(Ydb.unit_id)*(kb.score(kb.whatIf(Ydb,{xp=_db+ceb}))/deb-1)*100,ceb
end
kb.MAX_RELICS=6
