function kb.relicWorth(eeb,feb)
local geb=feb._unique_item_data and feb._unique_item_data._unique_relic_data
if not geb then
return 0
end
local heb=N.Items[feb.item_id]or{}
local ieb,jeb=V.types(eeb.unit_id)
if heb.main_damage_type and heb.main_damage_type~=cHe[2916]and heb.main_damage_type~=jeb then
return 0
end
local keb,leb=0,0
for meb,neb in pairs(geb._core_damage_type_buffs or{})do
if ieb[neb.damage_type]then
keb=keb+(tonumber(neb.mul)or 0)+(tonumber(neb.add_upg)or 0)*0.01+(tonumber(neb.pen)or 0)*0.001
leb=leb+(tonumber(neb.crit)or 0)
end
end
keb=keb+leb*0.5
local oeb=V.rows(eeb.unit_id)
local peb=oeb and oeb[oeb.max]
local qeb=(peb and tonumber(peb.cd)or 0)*V.mult(eeb,cHe[2666])
for reb,seb in pairs(geb._unique_relic_effects or{})do
local teb=type(seb.params)==cHe[2220]and seb.params or{}
if seb.id==cHe[3317]then
local ueb=math.min(1,(tonumber(teb.extra_damage)or 0)*qeb/math.max(1,tonumber(teb.time_interval)or 40))
local veb=V.DRONES and V.DRONES[eeb.unit_id]
if veb and veb.late and qeb>0 then
local web=1/qeb
ueb=ueb*web/(web+(tonumber(veb.max)or 0)*(tonumber(veb.late.dmg)or 0)*(tonumber(veb.hits)or 1)/math.max(0.1,tonumber(veb.late.cd)or 4))
end
keb=keb+ueb
elseif seb.id==cHe[3318]then
keb=keb+(tonumber(teb.dmg_buff)or 0)*0.25
elseif seb.id==cHe[3319]then
keb=keb+(tonumber(teb.dmg_buff)or 0)*leb
elseif seb.id==cHe[3320]then
if ieb.magic then
keb=0
else
keb=keb+(tonumber(teb.dmg_buff)or 0)*0.3
end
elseif seb.id==cHe[3321]then
if ieb.water_damage then
keb=keb+0.05
end
elseif seb.id==cHe[2366]then
local xeb=tonumber(teb.duration_buff)or tonumber(type(seb.static_params)==cHe[2220]and seb.static_params.duration_buff)or 2
local yeb,zeb=pcall(V.attackInfo,peb and peb.atk,peb and peb.range)
local Aeb,Beb=yeb and tonumber(zeb.burn)or 0,yeb and tonumber(zeb.dot)or 0
if Aeb<=0 then
local Ceb,Deb=pcall(pb.model,eeb.unit_id,yeb and zeb or nil,peb)
if Ceb and type(Deb)==cHe[2220]and(tonumber(Deb.burnDot)or 0)>0 then
Aeb,Beb=Deb.burnDot,Beb+(tonumber(Deb.dot)or 0)
end
end
keb=keb+Aeb*math.max(0,xeb-1)/(1+Beb)
end
end
return keb
end
function kb.relicPlan()
local Eeb=N.session()
if not Eeb then
return nil
end
local Feb=Eeb.inventory and Eeb.inventory.inventory_profile_data or{}
local Geb={}
for Heb,Ieb in ipairs(Feb.unique_items or{})do
if type(Ieb)==cHe[2220]and Ieb.uuid and(N.Items[Ieb.item_id]or{}).item_group==cHe[3253]then
table.insert(Geb,Ieb)
end
end
local Jeb={}
for Keb,Leb in ipairs(V.equipped())do
local Meb=Leb.data and Leb.data.rarity
if not V.isFarm(Leb.id)and(Meb==cHe[2803]or Meb==cHe[2804]or Meb==cHe[3315]or Meb==cHe[3322])then
local Neb=kb.share(Leb.id)
if not P.str.share[Leb.id]then
Neb=math.min(Neb,0.15)
end
local Oeb={}
for Peb,Qeb in ipairs(Geb)do
local Reb=kb.relicWorth(Leb.u,Qeb)*Neb*100
if Reb>0.01 then
table.insert(Oeb,{it=Qeb,w=Reb})
end
end
table.sort(Oeb,function(Seb,Teb)
if Seb.w~=Teb.w then
return Seb.w>Teb.w
end
return Seb.it.uuid<Teb.it.uuid
end)
local Ueb,Veb={},{}
for Web,Xeb in ipairs(Oeb)do
local Yeb=Veb[Xeb.it.item_id]or 0
if#Ueb<6 and Yeb<((N.Items[Xeb.it.item_id]or{}).unique_equip and 1 or 2)then
Veb[Xeb.it.item_id]=Yeb+1
table.insert(Ueb,Xeb)
end
end
if Leb.u._equipped_relic then
local Zeb=false
for _eb,afb in ipairs(Ueb)do
if afb.it.uuid==Leb.u._equipped_relic then
Zeb=true
end
end
local bfb=not Zeb and Eeb.inventory:get_item_by_uuid(Leb.u._equipped_relic)
if bfb then
table.insert(Ueb,{it=bfb,w=kb.relicWorth(Leb.u,bfb)*Neb*100})
end
end
table.insert(Jeb,{e=Leb,share=Neb,opts=Ueb})
end
end
local cfb,dfb={},-1
local efb,ffb,gfb={},{},{}
local function hfb(ifb,jfb)
if ifb> #Jeb then
if jfb>dfb then
dfb=jfb
cfb=table.clone(efb)
end
return
end
local kfb=Jeb[ifb]
efb[kfb.e.uuid]=nil
hfb(ifb+1,jfb)
for lfb,mfb in ipairs(kfb.opts)do
local nfb=(N.Items[mfb.it.item_id]or{}).unique_equip
if not ffb[mfb.it.uuid]and not(nfb and gfb[mfb.it.item_id])then
ffb[mfb.it.uuid]=true
if nfb then
gfb[mfb.it.item_id]=true
end
efb[kfb.e.uuid]=mfb.it.uuid
hfb(ifb+1,jfb+mfb.w+(mfb.it.uuid==kfb.e.u._equipped_relic and 0.01 or 0))
efb[kfb.e.uuid]=nil
ffb[mfb.it.uuid]=nil
if nfb then
gfb[mfb.it.item_id]=nil
end
end
end
end
hfb(1,0)
local ofb,pfb=0,{}
for qfb,rfb in ipairs(Jeb)do
local sfb=rfb.e.u._equipped_relic and Eeb.inventory:get_item_by_uuid(rfb.e.u._equipped_relic)
local tfb=sfb and kb.relicWorth(rfb.e.u,sfb)*rfb.share*100 or 0
ofb=ofb+tfb
local ufb=cfb[rfb.e.uuid]and Eeb.inventory:get_item_by_uuid(cfb[rfb.e.uuid])
local vfb=ufb and kb.relicWorth(rfb.e.u,ufb)*rfb.share*100 or 0
table.insert(pfb,string.format(cHe[3323],V.name(rfb.e.id),sfb and(N.Items[sfb.item_id]or{}).name or cHe[2814],tfb,ufb and(N.Items[ufb.item_id]or{}).name or cHe[2814],vfb))
end
return cfb,dfb-ofb,pfb,Jeb
end
function kb.relicsApply(wfb)
if not(O.team and O.teamRelics)or O.strDry then
