end
task.wait(1.2)
if Zfb.e.u._equipped_relic~=_fb then
F.log(1,cHe[3309],string.format(cHe[3329],(N.Items[(Cfb.inventory:get_item_by_uuid(_fb)or{}).item_id]or{}).name or cHe[3330],V.name(Zfb.e.id),Ifb(hgb)))
F.backoff(cHe[3325],300)
P.str.relicAt=0
return false
end
Xfb=Xfb+1
end
end
W._sigAt=nil
P.str.relicSig=W.teamSig()
