function kb.xpGuess(bhb)
local chb=bhb.level and N.Levels[bhb.level]
if not chb then
return 0
end
local dhb=math.min(9,tonumber(chb.story_world_rank)or tonumber(bhb.rank)or 9)
local ehb=tonumber(chb.story_level_rank)or 6
local fhb=(bhb.kind==cHe[2269]and 1.5 or 1)*(dhb>5 and 2 or 1)
local ghb=2.1564^(dhb-1)*(40+10*ehb)/fhb
if bhb.kind==cHe[2245]then
ghb=3*30*2.1564^(dhb-1)/fhb
end
local hhb=dhb>=9 and 0.3 or(dhb>=7 and 0.5 or 1)
return ghb*hhb*6
end
