cb.add(string.format(cHe[3343],Nhb,Hhb.name),Nhb,cHe[3344],string.format(cHe[3345],U.fmt(Uhb),Whb))
kb.note(string.format(cHe[3346],Hhb.name,Nhb,U.fmt(Uhb),Whb,math.abs(Uhb-Mhb)>Mhb*0.1 and string.format(cHe[3347],U.fmt(Mhb))or cHe[1139]))
else
kb.note(string.format(cHe[3348],Hhb.name,tostring(Qhb and Rhb or cHe[2767])))
F.backoff(cHe[3334],600)
end
end
