function eb.upgradeGain(WJb,XJb,YJb,ZJb,_Jb,aKb)
local bKb,cKb=XJb[YJb],XJb[YJb+1]
local dKb=(bKb.cd>0 and bKb.damage/bKb.cd or 0)
local eKb=(cKb.cd>0 and cKb.damage/cKb.cd or 0)*V.aoe(cKb.atk,cKb.range)/math.max(0.3,V.aoe(bKb.atk,bKb.range))
local fKb=dKb>0 and WJb*(eKb/dKb-1)or(aKb or 0)
local gKb=XJb[YJb+2]
if gKb and YJb+1<XJb.max and gKb.cd>0 and cKb.cd>0 and dKb>0 then
local hKb=WJb*((gKb.damage/gKb.cd)/dKb-1)
local iKb=ZJb+gKb.cost*_Jb
if hKb/iKb>fKb/ZJb then
fKb=fKb+(hKb/iKb*ZJb-fKb)*0.5
end
end
local jKb=(cKb.range or 0)>(bKb.range or 0)and(1+((cKb.range-bKb.range)/math.max(1,bKb.range)))or 1
return math.max(0,fKb)*jKb
end
function eb.dpsFor(kKb,lKb)
if lKb<=0 then
return 0
end
local mKb={}
for nKb,oKb in ipairs(kKb)do
if not oKb.farm and not oKb.grif and oKb.gain>0 then
table.insert(mKb,oKb)
end
end
table.sort(mKb,function(pKb,qKb)
return pKb.gain/pKb.cost>qKb.gain/qKb.cost
end)
local rKb,sKb=0,0
for tKb,uKb in ipairs(mKb)do
if lKb<=0 then
break
end
