function eb.shieldDps(wKb,xKb,yKb,zKb,AKb,BKb,CKb)
if(zKb or 0)<=0 or(wKb or 0)<=0 or(AKb or 0)<=0 then
return wKb or 0
end
xKb,yKb,BKb=math.max(0.3,xKb or 2),math.max(1,yKb or 1),BKb or 1
local DKb=wKb*BKb*xKb/yKb
return AKb*yKb/((zKb/math.max(1,CKb or 1)+math.max(1,AKb/DKb))*xKb)/BKb
end
function eb.shieldGain(EKb,FKb,GKb,HKb,IKb,JKb,KKb,LKb)
local MKb,NKb=V.attackInfo(FKb.atk,FKb.range),V.attackInfo(HKb.atk,HKb.range)
