local PKb=eb.shieldDps(GKb,(tonumber(HKb.cd)or 2)*(KKb or 1),NKb.n,IKb,JKb,LKb,NKb.hits)
local QKb=math.max(0,((tonumber(HKb.range)or 0)-(tonumber(FKb.range)or 0))/math.max(1,tonumber(FKb.range)or 1))
