return 0
end
return math.max(1,RKb or 1)*math.max(1,ZKb or 1)/math.max(0.3,SKb or 2)*math.min(XKb or 0,YKb or 0)
end
function eb.holdGain(aLb,bLb,cLb,dLb)
if not aLb or(bLb or 0)<=0 then
