local gLb,hLb=eLb>0 and eLb or fLb,eLb>0 and 1 or(tonumber(aLb.slowPct)or 0.3)
local iLb=hLb*gLb/(gLb+(tonumber(aLb.ccCd)or 8))
local jLb=iLb/math.max(0.1,1-iLb)
