end
function eb.bleedGain(kLb,lLb,mLb,nLb)
if(kLb or 0)<=0 then
return 0
end
local oLb=lLb or 0
for pLb,qLb in ipairs(mLb or{})do
oLb=math.max(oLb,(tonumber(qLb.hp)or 0)*0.5)
end
