function eb.keepsUp(vLb,wLb,xLb,yLb,zLb)
local ALb=vLb.coming
if not(ALb and#ALb>0 and vLb.waveSec)then
return true
end
local BLb=vLb.eff or 1
local CLb=vLb.money-xLb
local DLb=(vLb.teamDps or 0)*(vLb.shieldK or 1)+(yLb or 0)*BLb+eb.dpsFor(wLb,math.max(0,CLb))*BLb
local ELb=(vLb.farmNow or 0)+(zLb or 0)
local FLb=(vLb.roadSec or 130)*U.clamp(vLb.cover or 0.6,0.1,1)
