for HLb,ILb in ipairs(ALb)do
GLb=math.max(0,GLb+ILb.hp-DLb*vLb.waveSec)
local JLb=DLb*FLb
if GLb>JLb then
return false,HLb,JLb/math.max(1,GLb)
end
if HLb< #ALb then
DLb=DLb+eb.dpsFor(wLb,(ILb.reward or 0)+ELb)*BLb*(0.85^HLb)
