local PLb=LLb.attackers>0 and LLb.pressure<math.min(O.safeReach,MLb*0.75)and not LLb.piling and not OLb
local QLb=LLb.pressure>=math.min(O.dangerReach,MLb*0.9)or(LLb.piling and LLb.enemies>=18)
