for TLb,ULb in ipairs(KLb)do
if ULb.farm then
if O.farmUnits and ULb.gain>0 then
ULb.payback=ULb.cost/ULb.gain
if LLb.left-1>=ULb.payback+(LLb.farmSpare or O.farmSpare)and(not RLb or ULb.payback<RLb.payback)then
RLb=ULb
end
end
else
ULb.ratio=ULb.gain/math.max(1,ULb.cost)
if not SLb or ULb.ratio>SLb.ratio then
SLb=ULb
end
end
end
if LLb.leak and LLb.attackers>0 then
local VLb
for WLb,XLb in ipairs(KLb)do
local YLb=not LLb.airLeak or(XLb.e and bb.cardAir(XLb.e.id))
if XLb.place and not XLb.farm and not XLb.idol and not XLb.grif and YLb and XLb.cost<=LLb.money and not(XLb.e and V.allyBuff(XLb.e.id))and(not VLb or XLb.gain>VLb.gain)then
VLb=XLb
end
end
if VLb then
return VLb,string.format(cHe[4012],math.floor(LLb.leak*100))
end
end
local ZLb=LLb.future<LLb.wantLeft*1.1
local _Lb,aMb,bMb=true,nil,nil
if RLb then
_Lb,aMb,bMb=eb.keepsUp(LLb,KLb,RLb.cost,0,RLb.gain)
end
local cMb=LLb.coming and not eb.keepsUp(LLb,KLb,0,0,0)
local dMb=false
if bb.random and RLb and not QLb and LLb.attackers>=2 and RLb.payback<=LLb.left/3 then
local eMb=0
