if V.isFarm(gMb._stats.id.Value)then
eMb=eMb+1
end
end
dMb=not RLb.place or eMb<4
end
if cMb and LLb.attackers>0 then
QLb=true
end
if QLb and SLb and SLb.grif then
SLb=nil
for hMb,iMb in ipairs(KLb)do
