end
return qMb
end
local tMb,uMb
if LLb.attackers==0 and SLb then
local vMb=4*kMb
local wMb={}
for xMb,yMb in ipairs(KLb)do
if yMb.place and not yMb.farm and not yMb.grif then
table.insert(wMb,{o=yMb,v=lMb(yMb,nil,vMb)})
end
end
table.sort(wMb,function(zMb,AMb)
return zMb.v>AMb.v
end)
local BMb=LLb.opener and wMb[LLb.opener]and LLb.opener or 1
local CMb=wMb[BMb]and wMb[BMb].o
tMb,uMb=CMb or SLb,BMb>1 and cHe[4013]or cHe[4014]
elseif O.farmFirst and RLb and not QLb and not bb.random then
tMb=RLb
uMb=string.format(cHe[4015],RLb.payback,LLb.left)
elseif RLb and PLb and ZLb and not QLb and _Lb then
tMb=RLb
uMb=string.format(cHe[4016],RLb.payback,LLb.left,LLb.coming and#LLb.coming or 0)
elseif dMb then
tMb=RLb
uMb=string.format(cHe[4017],RLb.payback,LLb.left)
elseif SLb then
tMb=SLb
if cMb then
uMb=string.format(cHe[4018])
elseif QLb then
uMb=string.format(cHe[4019],math.floor(LLb.pressure*100),math.floor(MLb*100))
elseif RLb and not _Lb then
uMb=string.format(cHe[4020],aMb or 1,math.floor((bMb or 0)*100))
elseif RLb and OLb then
