DMb,FMb=HMb,IMb
end
end
end
end
if not DMb then
return nil,nil,string.format(cHe[4026],U.fmt(tMb.cost),tMb.what or cHe[2466],math.ceil((tMb.cost-LLb.money)/jMb),math.floor(jMb),uMb),{cost=tMb.cost,what=tMb.what,sec=math.ceil((tMb.cost-LLb.money)/jMb),rate=math.floor(jMb),why=uMb}
end
tMb,uMb=DMb,uMb..cHe[4027]
end
return tMb,uMb
end
