gb.LD_FIELDS={cHe[2608],cHe[4028],cHe[4029],cHe[4030],cHe[4031],cHe[4032],cHe[4033],cHe[4034],cHe[4035],cHe[4036],cHe[2245],cHe[4037],cHe[4038],cHe[4039],cHe[4040],cHe[4041],cHe[4042],cHe[4043],cHe[4044],cHe[4045],cHe[4046],cHe[4047],cHe[3031],cHe[4048],cHe[4049],cHe[4050]}
