function bb.buildPath()
bb.samples={}
local lzc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not lzc then
return
end
for mzc,nzc in pairs(lzc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[mzc.Name])then
local ozc={}
for pzc,qzc in ipairs(nzc.points or{})do
table.insert(ozc,qzc.part.Position)
end
local rzc=0
for szc=2,#ozc do
rzc=rzc+(ozc[szc]-ozc[szc-1]).Magnitude
end
local tzc=0
for uzc=2,#ozc do
local vzc,wzc=ozc[uzc-1],ozc[uzc]
local xzc=(wzc-vzc).Magnitude
local yzc=math.max(1,math.floor(xzc/2))
for zzc=0,yzc-1 do
local Azc=vzc:Lerp(wzc,zzc/yzc)
table.insert(bb.samples,{pos=Azc,prog=(tzc+xzc*zzc/yzc)/math.max(1,rzc),lane=mzc.Name})
end
tzc=tzc+xzc
end
if ozc[#ozc]then
table.insert(bb.samples,{pos=ozc[#ozc],prog=1,lane=mzc.Name})
end
end
end
pcall(bb.readHidden,lzc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Bzc=tonumber(bb.ld and bb.ld._portal_lanes)
local Czc=gb.laneList(bb.samples)
if Bzc and Bzc>=1 and Czc and#Czc>Bzc then
bb.laneWant=Bzc
