function bb.readHidden(Dzc)
local Ezc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Ezc)~=cHe[2220]or not next(Ezc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Fzc
for Gzc,Hzc in pairs(Dzc)do
if Ezc[Gzc.Name]and type(Hzc.points)==cHe[2220]and#Hzc.points>=2 then
local Izc={}
for Jzc,Kzc in ipairs(Hzc.points)do
Izc[Jzc]=U.flat(Kzc.part.Position)
end
local Lzc={}
for Mzc,Nzc in ipairs(bb.samples)do
local Ozc=tostring(Nzc.lane)
Lzc[Ozc]=Lzc[Ozc]or{}
table.insert(Lzc[Ozc],Nzc)
end
local Pzc,Qzc
for Rzc,Szc in pairs(Lzc)do
local Tzc=0
for Uzc=1,#Izc,math.max(1,math.floor(#Izc/20))do
local Vzc=math.huge
for Wzc,Xzc in ipairs(Szc)do
local Yzc=(U.flat(Xzc.pos)-Izc[Uzc]).Magnitude
if Yzc<Vzc then
Vzc=Yzc
end
end
Tzc=Tzc+Vzc
end
if not Qzc or Tzc<Qzc then
Pzc,Qzc=Rzc,Tzc
end
end
local Zzc,_zc,aAc,bAc,cAc,dAc={},nil,nil,nil,0,0
for eAc,fAc in ipairs(Izc)do
local gAc,hAc=nil,math.huge
for iAc,jAc in ipairs(Lzc[Pzc])do
local kAc=(U.flat(jAc.pos)-fAc).Magnitude
if kAc<hAc then
hAc,gAc=kAc,jAc.prog
end
end
dAc=math.max(dAc,hAc)
if aAc then
local lAc=gAc-aAc
local mAc=(lAc>0.002 and 1)or(lAc< -0.002 and-1)or bAc
if bAc and mAc and mAc~=bAc then
table.insert(Zzc,math.floor(aAc*1000+0.5)/1000)
end
bAc,cAc=mAc or bAc,cAc+math.abs(lAc)
else
_zc=gAc
end
aAc=gAc
if eAc%50==0 then
task.wait()
end
end
if aAc and dAc<=8 then
table.insert(Zzc,math.floor(aAc*1000+0.5)/1000)
Fzc=Fzc or{}
Fzc[Gzc.Name]={from=math.floor((_zc or 0)*1000+0.5)/1000,len=math.floor(cAc*1000+0.5)/1000,turns=Zzc,road=Pzc}
end
end
end
if not Fzc then
return
end
local nAc=bb.ld.map
P.maps[nAc]=P.maps[nAc]or{}
local oAc=P.maps[nAc].hidden
P.maps[nAc].hidden=Fzc
if type(oAc)~=cHe[2220]then
for pAc,qAc in pairs(Fzc)do
F.log(1,cHe[2901],string.format(cHe[4432],pAc,qAc.len,tostring(qAc.road),math.floor((#qAc.turns-1)/2)))
end
F.saveSoon()
end
end
