bb.probe.Size=Vector3 .new(MDc*2,2.5,MDc*2)
bb.probe.CFrame=CFrame.new(LDc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local NDc=U.flat(LDc)
local ODc=bb.grifZone
if ODc and type(IDc)==cHe[2220]and IDc.id~=V.GRIF.egg and not V.sacFodder(IDc.id)and(NDc-ODc.p).Magnitude<=ODc.r+1.5 then
return nil
end
