local SDc=RDc and RDc.Position or QDc:GetPivot().Position
local TDc=RDc and math.max(RDc.Size.X,RDc.Size.Z)/2 or 1.5
if(NDc-U.flat(SDc)).Magnitude<MDc+TDc then
return nil
end
end
if not JDc then
for UDc,VDc in ipairs(bb.blockers())do
if(NDc-VDc.p).Magnitude<MDc+VDc.r then
return nil
end
end
end
return LDc
end
function bb.buildCandidates()
bb.cands={}
