for XDc=1,#bb.samples,3 do
local YDc=bb.samples[XDc]
local ZDc=bb.samples[math.min(#bb.samples,XDc+1)]
local _Dc=U.flat(ZDc.pos-YDc.pos)
if _Dc.Magnitude<0.01 then
_Dc=Vector3 .new(1,0,0)
end
_Dc=_Dc.Unit
local aEc=Vector3 .new(-_Dc.Z,0,_Dc.X)
for bEc,cEc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for dEc,eEc in ipairs({1,-1})do
local fEc=YDc.pos+aEc*cEc*eEc
local gEc=string.format(cHe[4465],math.floor(fEc.X/1.5),math.floor(fEc.Z/1.5))
if not WDc[gEc]then
WDc[gEc]=true
table.insert(bb.cands,fEc)
end
end
end
end
end
function bb.coverage(hEc,iEc)
local jEc={}
for kEc,lEc in ipairs(hEc)do
local mEc=lEc._stats
if not V.isFarm(mEc.id.Value)and mEc:FindFirstChild(cHe[2483])then
table.insert(jEc,{p=U.flat(lEc:GetPivot().Position),r=mEc.range.Value*(V.SUMMONER[mEc.id.Value]and V.SUMMONER[mEc.id.Value].reach or 1),air=bb.canAir(lEc)})
end
end
local nEc,oEc=0,0
if#jEc>0 then
for pEc,qEc in ipairs(bb.samples)do
if qEc.prog>oEc then
local rEc=U.flat(qEc.pos)
for sEc,tEc in ipairs(jEc)do
if(rEc-tEc.p).Magnitude<=tEc.r then
if qEc.prog>nEc then
nEc=qEc.prog
end
if tEc.air then
oEc=qEc.prog
break
end
end
end
end
end
end
local uEc,vEc={},bb.laneCount
if vEc and vEc.n>=2 and#jEc>0 then
local wEc={}
for xEc,yEc in ipairs(bb.samples)do
local zEc=U.flat(yEc.pos)
for AEc,BEc in ipairs(jEc)do
if(zEc-BEc.p).Magnitude<=BEc.r then
local CEc=tostring(yEc.lane)
wEc[CEc]=(wEc[CEc]or 0)+1
if yEc.prog>(uEc[CEc]or 0)then
uEc[CEc]=yEc.prog
end
break
end
end
end
local DEc,EEc={},0
for FEc,GEc in pairs(vEc.by)do
DEc[FEc]=(wEc[FEc]or 0)/math.max(1,GEc)
EEc=math.max(EEc,DEc[FEc])
end
bb.laneW={}
for HEc,IEc in pairs(vEc.by)do
bb.laneW[HEc]=(vEc.avg/math.max(1,IEc))*(1+1.5*(EEc>0 and(1-DEc[HEc]/EEc)or 0))
end
bb.laneFrac=DEc
else
bb.laneW,bb.laneFrac=nil,nil
end
local JEc,KEc,LEc
if#jEc>0 then
for MEc,NEc in ipairs(iEc)do
local OEc=(bb.laneW and NEc.lane)and(uEc[tostring(NEc.lane)]or 0)or nEc
if NEc.hp>0 and NEc.prog>OEc+0.02 and NEc.prog>(JEc or 0)then
JEc,LEc=NEc.prog,bb.laneW and NEc.lane or nil
end
if NEc.hp>0 and NEc.fly and NEc.prog>oEc+0.02 then
KEc=true
end
end
end
local PEc= #jEc>0 and(bb.pressure or 0)>=nEc-0.08
return{covEnd=nEc,airEnd=oEc,leak=JEc,leakLane=LEc,covL=uEc,airLeak=KEc,push=PEc,units= #jEc}
end
