end
local gFc=V.rows(dFc)
if not(gFc and gFc.max)then
return bb.cardAir(dFc)and 0 or nil
end
local hFc=false
for iFc=0,gFc.max do
local jFc=gFc[iFc]and gFc[iFc].atk
if jFc and N.Attacks[jFc]and N.Attacks[jFc].targets_flying then
hFc=iFc
break
end
end
if hFc==false and bb.cardAir(dFc)then
hFc=0
end
V._airFrom[dFc]=hFc
