function bb.cover(vGc,wGc,xGc,yGc,zGc)
local AGc=0
local BGc=U.flat(vGc)
local CGc=xGc and P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
local DGc=bb.laneW
for EGc,FGc in ipairs(zGc and bb.samples or bb.hurtSamples())do
if(U.flat(FGc.pos)-BGc).Magnitude<=wGc then
local GGc=1
if CGc then
GGc=0.15+0.85*(tonumber(CGc[math.min(gb.BINS,math.floor(FGc.prog*gb.BINS)+1)])or 0)
end
if DGc then
GGc=GGc*(DGc[tostring(FGc.lane)]or 1)
end
if yGc then
if yGc.leak and FGc.prog>=yGc.leak-0.01 and(not yGc.leakLane or tostring(FGc.lane)==yGc.leakLane)then
GGc=GGc+3
