local HTc=GTc and type(GTc.mapSpots)==cHe[2220]and GTc.mapSpots[tostring(FTc)]or nil
return type(HTc)==cHe[2220]and HTc or{}
end
function bb.hiveUnitSpots(ITc,JTc)
local KTc=db.hive()
local LTc=KTc and type(KTc.unitSpots)==cHe[2220]and KTc.unitSpots[tostring(ITc)]or nil
local MTc=type(LTc)==cHe[2220]and LTc[tostring(JTc)]or nil
if type(MTc)~=cHe[2220]or type(MTc.spots)~=cHe[2220]then
return{},nil
end
return MTc.spots,tonumber(MTc.base)
end
function bb.nearSpot(NTc,OTc,PTc)
local QTc,RTc=nil,9
for STc,TTc in ipairs(NTc or{})do
local UTc=(TTc.X-OTc)^2+(TTc.Z-PTc)^2
if UTc<=RTc then
QTc,RTc=TTc,UTc
end
end
return QTc
end
function bb.baseRange(VTc)
local WTc=V.rows(VTc)
local XTc=WTc and WTc[WTc.max]and tonumber(WTc[WTc.max].range)
return XTc or(N.Units[VTc]and tonumber(N.Units[VTc].range))or nil
end
function bb.studyMoves(YTc,ZTc)
local _Tc=V.rows(YTc.id)
local aUc=V.range(YTc.e.u,_Tc.max)*ZTc
local bUc=aUc*aUc
local cUc,dUc={},{}
local eUc,fUc=bb.hurtSamples(),bb.sandLine()
for gUc,hUc in ipairs(YTc.spots or{})do
local iUc,jUc,kUc,lUc,mUc=0,0,0,0,0
for nUc,oUc in ipairs(eUc)do
local pUc,qUc=oUc.pos.X-hUc.X,oUc.pos.Z-hUc.Z
if pUc*pUc+qUc*qUc<=bUc then
kUc=kUc+1
local rUc=math.min(49,math.floor(oUc.prog*50))
if rUc<25 then
iUc=bit32 .bor(iUc,bit32 .lshift(1,rUc))
else
jUc=bit32 .bor(jUc,bit32 .lshift(1,rUc-25))
end
if oUc.prog-fUc<=0.3 then
lUc=lUc+1
elseif oUc.prog>=0.7 then
mUc=mUc+1
end
end
end
if kUc>0 then
local sUc=iUc..cHe[2367]..jUc
local tUc=cUc[sUc]
if not tUc then
tUc={p=hUc,lo=iUc,hi=jUc,n=kUc,early=lUc,late=mUc}
cUc[sUc]=tUc
table.insert(dUc,tUc)
elseif kUc>tUc.n then
tUc.p,tUc.n,tUc.early,tUc.late=hUc,kUc,lUc,mUc
end
end
if gUc%40==0 then
task.wait()
end
end
local uUc={}
for vUc,wUc in ipairs(dUc)do
local xUc=false
for yUc,zUc in ipairs(dUc)do
if vUc~=yUc and zUc.n>=wUc.n and bit32 .band(wUc.lo,zUc.lo)==wUc.lo and bit32 .band(wUc.hi,zUc.hi)==wUc.hi and(zUc.lo~=wUc.lo or zUc.hi~=wUc.hi or zUc.n>wUc.n)then
xUc=true
break
end
end
if not xUc then
table.insert(uUc,wUc)
end
if vUc%40==0 then
task.wait()
end
end
local AUc,BUc={},{}
local function CUc(DUc)
if DUc and not BUc[DUc]then
BUc[DUc]=true
table.insert(AUc,DUc)
end
end
table.sort(uUc,function(EUc,FUc)
return EUc.n>FUc.n
end)
for GUc=1,math.min(bb.STUDY_K,#uUc)do
CUc(uUc[GUc].p)
end
table.sort(uUc,function(HUc,IUc)
return HUc.early>IUc.early
end)
CUc(uUc[1]and uUc[1].p)
CUc(uUc[2]and uUc[2].p)
table.sort(uUc,function(JUc,KUc)
return JUc.late>KUc.late
end)
CUc(uUc[1]and uUc[1].p)
CUc(uUc[2]and uUc[2].p)
local LUc=0
for MUc,NUc in ipairs((bb.hiveUnitSpots(bb.ld and bb.ld.map,YTc.id)))do
local OUc=tonumber(NUc.x)and tonumber(NUc.z)and bb.nearSpot(YTc.spots,tonumber(NUc.x),tonumber(NUc.z))or nil
if OUc and not BUc[OUc]then
CUc(OUc)
LUc=LUc+1
end
end
for PUc,QUc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if LUc>=bb.STUDY_SHARED then
break
end
local RUc=false
for SUc,TUc in ipairs(type(QUc.units)==cHe[2220]and QUc.units or{})do
local UUc=TUc==YTc.id and aUc or((bb.baseRange(TUc)or 0)*ZTc)
if TUc==YTc.id or(UUc>0 and math.abs(UUc-aUc)<=0.3*aUc)then
RUc=true
break
end
end
local VUc=RUc and tonumber(QUc.x)and tonumber(QUc.z)and bb.nearSpot(YTc.spots,tonumber(QUc.x),tonumber(QUc.z))or nil
if VUc and not BUc[VUc]then
CUc(VUc)
LUc=LUc+1
end
end
return AUc,#dUc,#uUc,LUc
end
function bb.studyRun(WUc)
local XUc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-XUc<20)do
task.wait(1)
end
local function YUc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and not O.lowLag and F.where==cHe[2301]
end
if not YUc()then
return
end
local ZUc,_Uc,aVc=WUc.info,WUc.team,WUc.base
local bVc=ZUc.timeLimit~=nil
local cVc=bVc and 1 or math.max(1,tonumber(WUc.hard)or 1)
local dVc={cVc*0.95,cVc*1.05}
local eVc=bb.bookFor(ZUc)
local fVc={key=WUc.key,label=bb.label(),n=eVc and tonumber(eVc.n)or 0,run=0,timed=bVc,kills=ZUc.killScore and true or nil,hp=cVc,at=os.time()}
bb.study=fVc
local gVc,hVc,iVc,jVc,kVc={},0,0,0,0
for lVc,mVc in ipairs(WUc.attackers)do
local nVc,oVc,pVc,qVc=bb.studyMoves(mVc,WUc.scale)
gVc[mVc.id]=nVc
hVc,iVc,jVc,kVc=hVc+ #(mVc.spots or{}),iVc+oVc,jVc+ #nVc,kVc+qVc
if not YUc()then
return
end
end
fVc.moves=jVc
F.log(1,cHe[3007],string.format(cHe[4621],fVc.label,hVc,iVc,jVc,kVc>0 and string.format(cHe[4622],kVc)or cHe[1139]))
local rVc={}
local function sVc(tVc)
return{samples=bb.samples,cache=rVc,spots=tVc,style=aVc.style,list=aVc.list,hybridHill=aVc.hybridHill}
end
local function uVc(vVc)
local wVc=0
for xVc,yVc in pairs(vVc)do
local zVc=bb.spotRec(xVc,yVc)
if zVc then
wVc=wVc+(tonumber(zVc.wins)or 0)*200-((tonumber(zVc.runs)or 0)-(tonumber(zVc.wins)or 0))*1500
end
end
return wVc
end
local function AVc(BVc)
local CVc,DVc,EVc=0,0,0
for FVc,GVc in ipairs(dVc)do
local HVc=os.clock()
local IVc=gb.runRaw(ZUc,_Uc,{hpMul=GVc,layout=sVc(BVc),bg=true})
CVc,DVc,EVc=CVc+gb.objective(IVc),DVc+(tonumber(IVc.kills)or 0),EVc+(tonumber(IVc.wave)or 0)
task.wait(math.clamp((os.clock()-HVc)*3,0.25,WUc.pauseMax or 1.5))
if not YUc()then
return nil
end
end
fVc.n,fVc.run=fVc.n+1,fVc.run+1
return CVc/ #dVc*100+uVc(BVc),DVc/ #dVc,EVc/ #dVc
end
local function JVc(KVc)
local LVc={}
for MVc,NVc in pairs(KVc)do
LVc[MVc]=NVc
end
return LVc
end
local function OVc(PVc,QVc,RVc)
for SVc,TVc in pairs(PVc)do
if SVc~=QVc and(U.flat(TVc)-U.flat(RVc)).Magnitude<4.5 then
return true
end
end
return false
end
local UVc={spots=JVc(aVc.spots)}
UVc.s,UVc.kills,UVc.wave=AVc(UVc.spots)
if not UVc.s then
return bb.studyEnd(fVc,WUc,nil)
end
fVc.baseKills,fVc.baseWave=UVc.kills,UVc.wave
fVc.bestKills,fVc.bestWave=UVc.kills,UVc.wave
if eVc and eVc.aside==nil then
local VVc,WVc=JVc(UVc.spots),0
for XVc,YVc in ipairs(WUc.attackers)do
local ZVc=eVc.spots[YVc.id]
local _Vc=type(ZVc)==cHe[2220]and tonumber(ZVc[1])and tonumber(ZVc[3])and bb.nearSpot(YVc.spots,tonumber(ZVc[1]),tonumber(ZVc[3]))or nil
if _Vc and _Vc~=VVc[YVc.id]and not OVc(VVc,YVc.id,_Vc)then
VVc[YVc.id]=_Vc
WVc=WVc+1
end
end
if WVc>0 then
local aWc,bWc,cWc=AVc(VVc)
if not aWc then
return bb.studyEnd(fVc,WUc,UVc)
end
if aWc>UVc.s then
UVc={spots=VVc,s=aWc,kills=bWc,wave=cWc}
fVc.bestKills,fVc.bestWave=bWc,cWc
end
end
end
local dWc,eWc=U.now(),fVc.run
local function fWc(gWc)
if not(gWc.s and gWc.s>UVc.s+math.max(50,math.abs(UVc.s)*0.005))then
return false
end
UVc=gWc
fVc.bestKills,fVc.bestWave,fVc.better=gWc.kills,gWc.wave,(fVc.better or 0)+1
pcall(bb.bookSave,ZUc,WUc,UVc,fVc)
return true
end
local function hWc()
if fVc.run-eWc>=60 or U.now()-dWc>240 then
dWc,eWc=U.now(),fVc.run
F.log(1,cHe[3007],bb.studyWords(fVc))
end
end
local iWc={UVc}
for jWc,kWc in ipairs(WUc.attackers)do
local lWc={}
for mWc,nWc in ipairs(iWc)do
table.insert(lWc,nWc)
for oWc,pWc in ipairs(gVc[kWc.id]or{})do
if pWc~=nWc.spots[kWc.id]and not OVc(nWc.spots,kWc.id,pWc)then
local qWc=JVc(nWc.spots)
qWc[kWc.id]=pWc
local rWc,sWc,tWc=AVc(qWc)
if not rWc then
return bb.studyEnd(fVc,WUc,UVc)
end
local uWc={spots=qWc,s=rWc,kills=sWc,wave=tWc}
table.insert(lWc,uWc)
fWc(uWc)
hWc()
end
end
end
table.sort(lWc,function(vWc,wWc)
return(vWc.s or-1e18)>(wWc.s or-1e18)
end)
iWc={}
for xWc=1,math.min(bb.STUDY_BEAM,#lWc)do
table.insert(iWc,lWc[xWc])
end
end
local yWc={}
for zWc,AWc in ipairs(WUc.attackers)do
if gVc[AWc.id]and#gVc[AWc.id]>0 then
table.insert(yWc,AWc.id)
end
end
while YUc()and#yWc>0 do
local BWc=JVc(UVc.spots)
for CWc=1,math.min(2,#yWc)do
local DWc=yWc[math.random(#yWc)]
local EWc=gVc[DWc]
local FWc=EWc[math.random(#EWc)]
if not OVc(BWc,DWc,FWc)then
BWc[DWc]=FWc
end
end
local GWc,HWc,IWc=AVc(BWc)
if not GWc then
break
end
fWc({spots=BWc,s=GWc,kills=HWc,wave=IWc})
hWc()
end
bb.studyEnd(fVc,WUc,UVc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(JWc,KWc)
local LWc=N.PC.raycast(JWc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not LWc then
return nil
end
if not N.PC.is_valid_raycast_hit(LWc.Instance,KWc)then
return nil
end
local MWc=LWc.Position
if bb.blockedSpot(MWc)then
return nil
end
local NWc=(tonumber(KWc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(NWc*2,2.5,NWc*2)
bb.probe.CFrame=CFrame.new(MWc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return MWc
end
function bb.studyInfinite()
if O.mapStudy==false or O.lowLag or not(bb.info and bb.infinite)or bb.kind==cHe[2683]then
return
end
local OWc=bb.info
local function PWc()
return not F.alive or bb.finished or bb.result or F.where~=cHe[2301]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local QWc,RWc={},{}
for SWc,TWc in ipairs(bb.team or{})do
table.insert(QWc,TWc.u)
if not V.isFarm(TWc.id)and not V.allyBuff(TWc.id)and TWc.uuid~=bb.trainee and V.rows(TWc.id)then
local UWc,VWc=pcall(V.score,TWc.u,bb.mod)
table.insert(RWc,{e=TWc,id=TWc.id,sc=UWc and VWc or 0})
end
end
if#RWc==0 then
return
end
table.sort(RWc,function(WWc,XWc)
return WWc.sc>XWc.sc
end)
local function YWc()
local ZWc,_Wc={},0
for aXc,bXc in ipairs(RWc)do
for cXc,dXc in ipairs(bb.mine or{})do
local eXc=dXc:FindFirstChild(cHe[2292])
local fXc=eXc and eXc:FindFirstChild(cHe[2607])
if fXc and fXc.Value==bXc.e.uuid and eXc:FindFirstChild(cHe[2608])and eXc.id.Value==bXc.id then
ZWc[bXc.id]=dXc:GetPivot().Position
_Wc=_Wc+1
break
end
end
end
return ZWc,_Wc
end
local gXc=U.now()
local hXc,iXc=YWc()
while iXc< #RWc and U.now()-gXc<bb.STUDY_INF_WAIT do
task.wait(5)
if PWc()then
return
end
hXc,iXc=YWc()
end
if iXc==0 or PWc()then
return
end
local jXc={}
local function kXc(lXc)
local mXc=lXc.hybrid_placement and not lXc.hill_unit
local nXc=mXc and bb.hybridHill
local oXc=((lXc.hill_unit or nXc)and cHe[3033]or(mXc and cHe[4544])or cHe[4545])..cHe[2367]..tostring(lXc.override_hitbox_radius or cHe[1139])
if jXc[oXc]then
return jXc[oXc]
end
local pXc={}
local qXc=nXc and bb.hillData(lXc)or lXc
for rXc,sXc in ipairs(bb.cands or{})do
local tXc=bb.validOpen(sXc,qXc)
if tXc then
table.insert(pXc,tXc)
end
if rXc%40==0 then
task.wait()
end
end
jXc[oXc]=pXc
return pXc
end
local uXc={info=OWc,team=gb.teamFrom(QWc,OWc.map),key=bb.bookKey(OWc),hard=1,scale=tonumber(OWc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local vXc={spots={},style=cHe[3201],hybridHill=bb.hybridHill and true or false}
for wXc,xXc in ipairs(RWc)do
local yXc=(gb.holds(xXc.id)and not V.killFed(xXc.id))and true or false
local zXc=yXc and{}or table.clone(kXc(xXc.e.data))
if PWc()then
return
end
local AXc=hXc[xXc.id]
if AXc then
local BXc=bb.nearSpot(zXc,AXc.X,AXc.Z)
if not BXc then
BXc=AXc
table.insert(zXc,AXc)
end
vXc.spots[xXc.id]=BXc
end
if#zXc>0 then
table.insert(uXc.attackers,{id=xXc.id,e=xXc.e,spots=zXc})
end
end
uXc.base=vXc
bb.studyPool=uXc
F.log(1,cHe[3007],string.format(cHe[4623],bb.label(),iXc))
bb.studyRun(uXc)
end
function bb.studyWords(CXc)
if type(CXc)~=cHe[2220]then
return cHe[1139]
end
local function DXc(EXc,FXc)
return CXc.kills and string.format(cHe[4559],math.floor((tonumber(EXc)or 0)+0.5))or string.format(cHe[4624],tonumber(FXc)or 0,tonumber(CXc.hp)or 1)
end
return string.format(cHe[4625],tostring(CXc.label),tonumber(CXc.n)or 0,tonumber(CXc.run)or 0,DXc(CXc.bestKills,CXc.bestWave),DXc(CXc.baseKills,CXc.baseWave),(CXc.better or 0)>0 and cHe[4626]or cHe[1139])
end
function bb.bookSave(GXc,HXc,IXc,JXc)
P.mapBook=type(P.mapBook)==cHe[2220]and P.mapBook or{}
local KXc={}
for LXc,MXc in pairs(IXc.spots or{})do
KXc[LXc]={math.floor(MXc.X*10+0.5)/10,math.floor(MXc.Y*10+0.5)/10,math.floor(MXc.Z*10+0.5)/10}
end
P.mapBook[HXc.key]={spots=KXc,style=HXc.base.style,hp=JXc.hp,n=JXc.n,kills=IXc.kills and math.floor(IXc.kills+0.5)or nil,wave=IXc.wave and math.floor(IXc.wave*10+0.5)/10 or nil,base=JXc.baseWave and math.floor(JXc.baseWave*10+0.5)/10 or nil,label=JXc.label,map=GXc.map,killScore=JXc.kills,at=os.time()}
local NXc={}
for OXc,PXc in pairs(P.mapBook)do
table.insert(NXc,{k=OXc,at=type(PXc)==cHe[2220]and tonumber(PXc.at)or 0})
end
if#NXc>bb.BOOK_MAX then
table.sort(NXc,function(QXc,RXc)
return QXc.at>RXc.at
end)
for SXc=bb.BOOK_MAX+1,#NXc do
P.mapBook[NXc[SXc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(TXc,UXc,VXc)
if type(TXc)~=cHe[2220]or TXc.ended then
return
end
TXc.ended=true
if VXc and UXc then
local WXc=bb.bookFor(UXc.info)
if WXc then
WXc.n=TXc.n
F.saveSoon()
elseif TXc.run>0 then
pcall(bb.bookSave,UXc.info,UXc,VXc,TXc)
end
end
if TXc.run>0 then
F.log(1,cHe[3007],bb.studyWords(TXc))
end
end
function bb.studyReport()
