bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(oYc,pYc)
local qYc=bb.bookKey(oYc)
P.layoutRec=type(P.layoutRec)==cHe[2220]and P.layoutRec or{}
local rYc=P.layoutRec[qYc]
if type(rYc)~=cHe[2220]then
if not pYc then
return nil
end
rYc={at=os.time()}
P.layoutRec[qYc]=rYc
if U.count(P.layoutRec)>80 then
