function bb.learn()
local knd=bb.calRun and bb.calRun.potBy
if type(knd)~=cHe[2220]then
return
end
pcall(bb.sampleHelpers,true)
local lnd={}
for mnd,nnd in pairs(bb.ownDealt or{})do
if not V.isFarm(nnd.id)then
lnd[nnd.id]=(lnd[nnd.id]or 0)+(tonumber(nnd.v)or 0)
end
end
for ond,pnd in pairs(bb.helperDealt or{})do
if pnd.owner and V.SUMMONER[pnd.owner]and not V.droneHelper(pnd)then
lnd[pnd.owner]=(lnd[pnd.owner]or 0)+(tonumber(pnd.v)or 0)
end
end
local qnd=type(bb.calRun.potExp)==cHe[2220]and bb.calRun.potExp or{}
local rnd,snd=0,0
local tnd={}
for und,vnd in pairs(knd)do
if vnd>0 then
rnd,snd=rnd+(lnd[und]or 0),snd+vnd
local wnd=tonumber(qnd[und])or vnd
if wnd>0 then
table.insert(tnd,{id=und,r=(lnd[und]or 0)/wnd,w=wnd})
end
end
end
if rnd<=0 or snd<=0 then
return
end
table.sort(tnd,function(xnd,ynd)
return xnd.r<ynd.r
end)
local function znd(And)
local Bnd,Cnd=0,0
for Dnd,End in ipairs(tnd)do
if End.id~=And then
Bnd=Bnd+End.w
end
end
if Bnd<=0 then
return nil
end
for Fnd,Gnd in ipairs(tnd)do
if Gnd.id~=And then
Cnd=Cnd+Gnd.w
if Cnd>=Bnd/2 then
return Gnd.r
end
end
end
end
bb.lastEff={}
for Hnd,Ind in pairs(knd)do
local Jnd=znd(Hnd)
if Ind>0 and Ind/snd>0.02 and Jnd and Jnd>0 then
local Knd=P.learn[Hnd]or{eff=1,n=0,v=6}
V.learnUp(Hnd,Knd)
local Lnd=math.max(0.02,0.25*math.sqrt(30/(30+Knd.n)))
local Mnd=U.clamp(((lnd[Hnd]or 0)/Ind)/Jnd,0.2,6)
bb.lastEff[Hnd]=math.floor(Mnd*1000+0.5)/1000
Knd.eff=Knd.eff+(Mnd-Knd.eff)*Lnd
Knd.n=Knd.n+1
P.learn[Hnd]=Knd
end
end
local Nnd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Nnd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==cHe[2220]and P.mapLearn or{}
local Ond=type(P.mapLearn[Nnd])==cHe[2220]and P.mapLearn[Nnd]or{}
for Pnd,Qnd in pairs(bb.lastEff)do
local Rnd=type(Ond[Pnd])==cHe[2220]and Ond[Pnd]or{eff=Qnd,n=0,v=6}
if(tonumber(Rnd.v)or 0)<4 then
Rnd.eff,Rnd.v=(tonumber(Rnd.eff)or Qnd)*V.secRescale(Pnd),4
end
if(tonumber(Rnd.v)or 0)<5 then
Rnd.eff,Rnd.v=(tonumber(Rnd.eff)or Qnd)*(V.sumRescale(Pnd)or 1),5
end
if(tonumber(Rnd.v)or 0)<6 then
Rnd.eff,Rnd.v=(tonumber(Rnd.eff)or Qnd)*(1-(V.SUMMONER[Pnd]and V.SUMMONER[Pnd].droneShare or 0)),6
end
local Snd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Rnd.n)or 0))))
Rnd.eff=(tonumber(Rnd.n)or 0)==0 and Qnd or((tonumber(Rnd.eff)or Qnd)+(Qnd-(tonumber(Rnd.eff)or Qnd))*Snd)
Rnd.n=(tonumber(Rnd.n)or 0)+1
Ond[Pnd]=Rnd
end
Ond._at=os.time()
P.mapLearn[Nnd]=Ond
if U.count(P.mapLearn)>80 then
local Tnd,Und
for Vnd,Wnd in pairs(P.mapLearn)do
if not Und or(tonumber(Wnd._at)or 0)<Und then
Tnd,Und=Vnd,tonumber(Wnd._at)or 0
end
end
P.mapLearn[Tnd]=nil
end
end
end
