local Ftd=bb.bestRate or 0
if Etd or Ftd<=0 then
return
end
local Gtd=bb.wave()
local Htd=math.max(0,(bb.total or 30)-Gtd)
local Itd=bb.mergePlan
local Jtd=bb.airLow()
local Ktd,Ltd,Mtd
for Ntd,Otd in ipairs(bb.mine)do
local Ptd=Otd._stats
local Qtd=Ptd.id.Value
local Rtd=N.Units[Qtd]
local Std=Ptd:FindFirstChild(cHe[4474])and tonumber(Ptd.total_spent.Value)or 0
if Rtd and not Rtd.unsellable and Std>0 and not V.allyBuff(Qtd)and not V.idol(Qtd)and not(Itd and Itd.id==Qtd)then
