local Wtd=Vtd*Htd
if Std>Wtd*1.2 then
Ttd=(Std-Wtd)*Ftd
Utd=string.format(cHe[4962],U.fmt(Wtd),U.fmt(Std))
end
elseif Gtd>=10 and Htd>2 and Std>=5000 and(bb.upRate[Otd]or 0)<Ftd/3 and bb.progressAt(Otd:GetPivot().Position)<0.8 and not(Jtd and bb.canAir(Otd))then
local Xtd,Ytd=pcall(bb.liveDps,Otd,Qtd)
Ytd=Xtd and Ytd or math.huge
if Std*Ftd>3*Ytd and Ytd<0.1*(bb.teamDps or 0)then
Ttd=Std*Ftd-Ytd
Utd=string.format(cHe[4963],U.fmt(Std))
end
end
if Ttd and(not Ltd or Ttd>Ltd)then
Ktd,Ltd,Mtd=Otd,Ttd,Utd
end
end
end
if not Ktd then
return
end
bb.spellBusy=true
task.spawn(function()
local Ztd=V.name(Ktd._stats.id.Value)
local _td=F.request(cHe[4954],cHe[4955],Btd,Ktd)
task.wait(1.5)
if _td and(N.session().ingame_spells or{})[Btd]~=cHe[4948]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,cHe[4934],string.format(cHe[4964],Ztd,Mtd))
F.status(cHe[4817],cHe[4965]..Ztd)
else
F.backoff(cHe[4954],15)
F.log(2,cHe[4934],cHe[4966]..Ztd)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(aud,bud)
local cud=(bud.t or 0)-(aud.t or 0)
if cud<bb.BASE_WIN-1 then
return false
end
local dud=((tonumber(aud.base)or 0)-(tonumber(bud.base)or 0))/cud
if dud<=0 or(tonumber(bud.base)or 0)<=0 then
return false
end
local eud=bud.base/dud
local fud,gud=0,0
local hud,iud=aud.foes or{},bud.foes or{}
for jud,kud in pairs(iud)do
if kud.prog>=bb.BASE_END then
fud=fud+kud.hp
local lud=hud[jud]
if lud then
gud=gud+math.max(0,lud.hp-kud.hp)
end
end
end
for mud,nud in pairs(hud)do
if nud.prog>=bb.BASE_END and not iud[mud]then
gud=gud+nud.hp
end
end
if fud<=0 then
return false
end
local oud=gud/cud
local pud=oud>0 and fud/oud or math.huge
local qud={baseTime=eud,loss=dud,atEnd=fud,rate=oud,killTime=pud}
return eud<bb.BASE_SOON and pud>eud*bb.BASE_MARGIN,qud
end
