function bb.leakStep(bvd)
if not bvd then
if bb.kind~=cHe[2246]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local cvd=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==cHe[2220]and P.dg.bails or{}
if not bvd and(tonumber(P.dg.bails[cvd])or 0)>=bb.BAIL_MAX then
return
end
local dvd=workspace:FindFirstChild(cHe[4979])and workspace._BASES:FindFirstChild(cHe[4433])
local evd=dvd and dvd:FindFirstChild(cHe[4679])and dvd.base:FindFirstChild(cHe[4680])
local fvd=evd and evd:FindFirstChildOfClass(cHe[2624])
if not fvd or fvd.Health<=0 then
return
end
local gvd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local hvd=U.now()
bb.leakTrack=bb.leakTrack or{}
local ivd=bb.leakTrack
local jvd,kvd={},nil
for lvd,mvd in ipairs(bb.enemies or{})do
if mvd.m then
jvd[mvd.m]=true
local nvd,ovd=tonumber(mvd.hp)or 0,tonumber(mvd.prog)or 0
local pvd=ivd[mvd.m]
if not pvd then
ivd[mvd.m]={t=hvd,hp=nvd,prog=ovd}
else
if hvd-pvd.t>=bb.LEAK_WIN then
pvd.pace,pvd.net=(ovd-pvd.prog)/(hvd-pvd.t),(pvd.hp-nvd)/(hvd-pvd.t)
pvd.t,pvd.hp,pvd.prog=hvd,nvd,ovd
end
if pvd.pace and pvd.pace>0 and nvd>0 then
local qvd=(1-ovd)/pvd.pace
local rvd=math.max(0,pvd.net or 0)
local svd=nvd-rvd*qvd
if svd>0 and qvd<=bb.LEAK_SOON and qvd>=bb.LEAK_MIN then
local tvd=mvd.m:FindFirstChildOfClass(cHe[2624])
local uvd=fvd.Health/math.max(1,gvd*(tvd and tvd.MaxHealth or nvd))
local vvd=rvd>0 and svd/rvd or math.huge
if vvd>uvd*bb.LEAK_MARGIN and(qvd<=bb.LEAK_AHEAD or bb.leakAhead(mvd)==0)and(not kvd or qvd<kvd.left)then
kvd={left=qvd,arriving=svd,net=rvd,baseTime=uvd,hp=nvd}
end
end
end
end
end
end
for wvd in pairs(ivd)do
if not jvd[wvd]then
ivd[wvd]=nil
end
end
if bvd then
return kvd~=nil,kvd
end
if not kvd then
return
end
bb.bailNote(cvd,cHe[4973])
F.log(1,cHe[2901],string.format(cHe[4982],bb.wave(),tonumber(bb.total)or 0,math.floor(kvd.left+0.5),U.fmt(kvd.hp),U.fmt(kvd.arriving),U.fmt(kvd.net),kvd.baseTime))
pcall(F.saveNow)
bb.toLobby(cHe[4981])
end
