YCd,ZCd=mDd,nDd
elseif mDd then
bb.spellWant=bb.spellWant or{cost=10000,why=cHe[5036]..nDd..cHe[2894]}
end
elseif XCd==cHe[2318]and DCd>=10000 and not ECd and bb.summonWorth()then
YCd,ZCd=false,cHe[5037]
elseif XCd==cHe[4947]and DCd>=2500 and not ECd and bb.summonWorth()then
YCd,ZCd=false,cHe[5038]
end
if ZCd then
bb.spellBusy=true
local oDd={}
for pDd,qDd in ipairs(workspace._UNITS:GetChildren())do
oDd[qDd]=true
end
local rDd
if YCd then
local sDd=YCd._stats
local tDd,uDd=pcall(bb.liveDps,YCd,sDd.id.Value)
rDd={id=sDd.id.Value,pos=YCd:GetPivot().Position,dps=tDd and tonumber(uDd)or 0,lvl=sDd.upgrade.Value,spent=sDd:FindFirstChild(cHe[4474])and tonumber(sDd.total_spent.Value)or 0}
end
task.spawn(function()
local vDd
if YCd then
vDd=F.request(cHe[4954],cHe[4955],WCd,YCd)
else
vDd=F.request(cHe[4954],cHe[4955],WCd)
end
task.wait(1.5)
local wDd=YCd and V.name(YCd._stats.id.Value)or cHe[1139]
if vDd and(N.session().ingame_spells or{})[WCd]~=XCd then
F.log(1,cHe[4934],string.format(cHe[5039],bb.SPELL_NAMES[XCd]or tostring(XCd),YCd and(cHe[2816]..wDd)or cHe[1139],ZCd))
F.status(cHe[4817],string.format(cHe[5040],bb.SPELL_NAMES[XCd]or tostring(XCd),YCd and(cHe[2816]..wDd)or cHe[1139],ZCd))
if XCd==cHe[4946]then
if rDd and V.isFarm(rDd.id)then
pcall(bb.farmMergeMeasure,YCd)
