bb.buffCount[YCd]=(bb.buffCount[YCd]or 0)+1
end
if(XCd==cHe[5010]or XCd==cHe[4943])and rDd then
pcall(bb.newUnitMeasure,XCd,YCd,wDd,rDd,oDd)
end
else
F.backoff(cHe[4954],15)
F.log(2,cHe[4934],tostring(XCd)..cHe[5041]..(YCd and(cHe[2816]..wDd)or cHe[1139]))
end
bb.spellBusy=false
end)
return
end
end
