function bb.trainCount()
local xDd=P.train.on
if not(xDd and bb.trainee)then
return
end
local yDd=0
for zDd,ADd in ipairs(bb.mine)do
local BDd=ADd._stats
local CDd=BDd:FindFirstChild(cHe[2607])and BDd.uuid.Value
local DDd=CDd==bb.trainee and BDd:FindFirstChild(xDd.what==cHe[2884]and cHe[5042]or cHe[2620])
if DDd then
yDd=yDd+(tonumber(DDd.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,yDd)
F.status(cHe[3523],string.format(cHe[5043],V.name(xDd.id),bb.trainTk,xDd.what,U.fmt(xDd.have+(xDd.got or 0)+bb.trainTk),U.fmt(xDd.need)))
end
function bb.trainDone(EDd,FDd)
local GDd=P.train.on
if not(GDd and bb.trainee)then
return
end
bb.trainCount()
local HDd=bb.trainTk or 0
GDd.got=(GDd.got or 0)+HDd
local IDd=P.trainSim[EDd]and tonumber(P.trainSim[EDd].tk)
if not bb.joinedMid then
local JDd=P.train.real[EDd]or{n=0,sum=0}
JDd.n,JDd.sum=JDd.n+1,JDd.sum+HDd
P.train.real[EDd]=JDd
if IDd and IDd>0 then
local KDd=P.train.cal
KDd.real,KDd.sim,KDd.n=(KDd.real or 0)+HDd,(KDd.sim or 0)+IDd,(KDd.n or 0)+1
end
end
table.insert(P.train.log,1,{key=EDd,got=HDd,won=FDd,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,cHe[3516],string.format(cHe[5044],V.name(GDd.id),HDd,GDd.what,FDd and cHe[2998]or cHe[2999],IDd and string.format(cHe[5045],IDd)or cHe[1139],U.fmt(ib.realHave(GDd)),U.fmt(GDd.need)))
if not FDd then
P.train.bad[EDd]=os.time()+3600
F.log(1,cHe[3516],cHe[5046])
end
end
function bb.realKills()
local LDd=M:FindFirstChild(cHe[2292])
local MDd=LDd and LDd:FindFirstChild(cHe[2884])
return MDd and tonumber(MDd.Value)or nil
end
bb.SKIP_LOOK={every=2,upTo=20}
function bb.skipSafe()
if bb.noBuy or bb.trialId or bb.stopping or bb.finished then
return false,cHe[5047]
end
local NDd,ODd=bb.wave(),tonumber(bb.total)or 0
if ODd>0 and NDd>=ODd and not bb.infinite then
return false,cHe[5048]
end
if#(bb.mine or{})==0 then
return false,cHe[5049]
end
if bb.depth and bb.depth.leak then
return false,cHe[5050]
end
for PDd,QDd in ipairs(bb.enemies or{})do
if QDd.boss then
return false,cHe[5051]
end
end
local RDd=(bb.depth and(bb.depth.units or 0)>0 and tonumber(bb.depth.covEnd))or 1
local SDd=tonumber(bb.pressure)or 0
local TDd=math.min(O.safeReach or 0.45,RDd*0.75)
if SDd>=TDd then
return false,string.format(cHe[5052],math.floor(SDd*100+0.5))
end
return true,string.format(cHe[5053],math.floor(SDd*100+0.5),math.floor(RDd*100+0.5))
end
function bb.skipVote()
if O.skipVote==false or not O.master or not O.battle or P.pauseAll or bb.skipBusy then
return
end
local UDd,VDd=pcall(function()
return M._settings.autoskip_waves.Value
end)
if UDd and VDd==true then
return
end
bb.skipBusy=true
local WDd,XDd=bb.wave(),U.now()
local YDd
while F.alive and bb.skipOpen and not bb.finished and bb.wave()==WDd and U.now()-XDd<bb.SKIP_LOOK.upTo do
local ZDd,_Dd=bb.skipSafe()
YDd=_Dd
if ZDd then
local aEd=F.request(cHe[5054],cHe[3942])
if aEd then
bb.skipVotes=(bb.skipVotes or 0)+1
if bb.skipVotes==1 then
F.log(1,cHe[2901],string.format(cHe[5055],WDd,tostring(_Dd)))
end
end
YDd=nil
break
end
task.wait(bb.SKIP_LOOK.every)
end
if YDd and not bb.skipSaid then
bb.skipSaid=true
F.log(2,cHe[2901],string.format(cHe[5056],WDd,YDd))
end
bb.skipBusy=false
end
bb.TO_LOBBY_WAIT=30
function bb.toLobby(bEd)
F.req.back.lobby=nil
local cEd,dEd=F.request(cHe[2300],cHe[3939])
if not(bb.leavingAt and U.now()-bb.leavingAt<60)then
bb.leavingAt=U.now()
task.spawn(function()
local eEd=U.now()
while F.alive and U.now()-eEd<bb.TO_LOBBY_WAIT do
if ab.teleportingNow()then
return
end
task.wait(0.5)
end
if not F.alive or ab.teleportingNow()then
return
end
F.log(1,cHe[2901],string.format(cHe[5057],tostring(bEd or cHe[5058]),bb.TO_LOBBY_WAIT,cEd and cHe[5059]or tostring(dEd)))
ab.toLobbyPlace(bEd or cHe[5058])
